1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export interface ScenarioResult {
47	  results: StepResult[];
48	}
49	
50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	const CURSE_SURCHARGE_PERCENT = 50;
53	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
54	const ENCHANTMENT_SURCHARGE_PERCENT = 30;
55	const LOYALTY_YEARS = 2;
56	const LOYALTY_DISCOUNT_PERCENT = 20;
57	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
58	
59	/** What the MHPCO knows about a kind of item it will insure: what insuring
60	 *  one costs (`basePremium`), and what one is insured FOR (`insuranceValue`,
61	 *  from which the cap is derived — never from premiums). One entry per kind,
62	 *  so the two figures for a kind cannot drift apart. */
63	interface ItemKind {
64	  basePremium: number;
65	  insuranceValue: number;
66	}
67	
68	/** The MHPCO's price list. */
69	const ITEM_KINDS: Record<string, ItemKind> = {
70	  sword: { basePremium: 100, insuranceValue: 1000 },
71	  amulet: { basePremium: 60, insuranceValue: 600 },
72	  staff: { basePremium: 80, insuranceValue: 800 },
73	  potion: { basePremium: 40, insuranceValue: 400 },
74	  rune: { basePremium: 25, insuranceValue: 250 },
75	  moonstone: { basePremium: 25, insuranceValue: 250 },
76	};
77	
78	const basePremiumOfType = (type: string): number =>
79	  ITEM_KINDS[type].basePremium;
80	
81	const insuranceValueOfType = (type: string): number =>
82	  ITEM_KINDS[type].insuranceValue;
83	
84	const DEDUCTIBLE_PER_DAMAGED_ITEM = 100;
85	const CAP_MULTIPLE = 2;
86	
87	/** The enchantment level from which a CLAIM is only half reimbursed. A claim
88	 *  rule, unrelated to ENCHANTMENT_SURCHARGE_LEVEL, which gates a premium
89	 *  surcharge — the two thresholds differ and move independently. */
90	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
91	const HALF_REIMBURSEMENT_PERCENT = 50;
92	
93	/** Modifiers are expressed as an amount to add, never as a factor to multiply
94	 *  by, so that they stay additive against their base and so that the integer
95	 *  numerator keeps float artifacts out of the final rounding
96	 *  (100 * 1.1 === 110.000…1, but (100 * 10) / 100 === 10 exactly). */
97	const percentOf = (amount: number, percent: number): number =>
98	  (amount * percent) / 100;
99	
100	/** Rounds up — premiums round in the MHPCO's favour. */
101	const roundPremium = (amount: number): number => Math.ceil(amount);
102	
103	const COMPONENT_BLOCK_SIZE = 3;
104	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
105	
106	const COMPONENT_TYPES = ["rune", "moonstone"];
107	
108	const isComponent = (item: Item): boolean =>
109	  COMPONENT_TYPES.includes(item.type);
110	
111	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
112	
113	const countByType = (items: Item[]): Map<string, number> => {
114	  const counts = new Map<string, number>();
115	  for (const item of items) {
116	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
117	  }
118	  return counts;
119	};
120	
121	/** A block is exactly three alike components, priced as a unit rather than
122	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
123	const componentGroupBasePremium = ([type, count]: [string, number]): number =>
124	  count === COMPONENT_BLOCK_SIZE
125	    ? COMPONENT_BLOCK_BASE_PREMIUM
126	    : count * basePremiumOfType(type);
127	
128	const sum = (amounts: number[]): number =>
129	  amounts.reduce((total, amount) => total + amount, 0);
130	
131	const policyBasePremium = (items: Item[]): number => {
132	  const mainItems = items.filter((item) => !isComponent(item));
133	  const componentGroups = [...countByType(items.filter(isComponent))];
134	
135	  return (
136	    sum(mainItems.map(itemBasePremium)) +
137	    sum(componentGroups.map(componentGroupBasePremium))
138	  );
139	};
140	
141	interface ItemModifierRule {
142	  appliesTo: (item: Item) => boolean;
143	  percent: number;
144	}
145	
146	/** Every item-scoped modifier, as a rule that either applies to an item or
147	 *  does not. Applicable rules stack. */
148	const ITEM_MODIFIER_RULES: ItemModifierRule[] = [
149	  {
150	    appliesTo: (item) => item.cursed === true,
151	    percent: CURSE_SURCHARGE_PERCENT,
152	  },
153	  {
154	    appliesTo: (item) => (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL,
155	    percent: ENCHANTMENT_SURCHARGE_PERCENT,
156	  },
157	];
158	
159	/** Item-scoped modifiers apply to the affected item's own base premium,
160	 *  not to the policy total. */
161	const itemModifierAmount = (item: Item): number =>
162	  sum(
163	    ITEM_MODIFIER_RULES.filter((rule) => rule.appliesTo(item)).map((rule) =>
164	      percentOf(itemBasePremium(item), rule.percent),
165	    ),
166	  );
167	
168	/** A policy written by a quote step, as later claim steps see it. The insured
169	 *  items are kept because a damage entry names only a type, while the clauses
170	 *  that govern its reimbursement depend on the insured item itself. */
171	interface Policy {
172	  remainingCap: number;
173	  items: Item[];
174	}
175	
176	/** What a step leaves behind for the steps after it. Steps are not
177	 *  independent: a quote is priced against how many contracts precede it, and
178	 *  a claim is paid against a policy an earlier quote wrote, so running a
179	 *  scenario threads this state from each step to the next. */
180	interface ScenarioState {
181	  customer: Customer;
182	  precedingContracts: number;
183	  /** Keyed by the zero-based index of the quote step that wrote the policy —
184	   *  which is what a claim step's `policy` field refers to. */
185	  policiesByStep: Record<number, Policy>;
186	}
187	
188	const initialState = (customer: Customer): ScenarioState => ({
189	  customer,
190	  precedingContracts: 0,
191	  policiesByStep: {},
192	});
193	
194	/** A step's outcome: what it reports, and the state the next step sees. */
195	interface StepOutcome {
196	  result: StepResult;
197	  state: ScenarioState;
198	}
199	
200	/** What a policy-wide rule may look at: the customer, plus where this quote
201	 *  sits in the customer's history of contracts. A pricing view of the
202	 *  scenario state — rules read it, they never advance it. */
203	type PolicyContext = Readonly<ScenarioState>;
204	
205	interface PolicyModifierRule {
206	  appliesTo: (context: PolicyContext) => boolean;
207	  /** Signed: positive surcharges, negative discounts. */
208	  percent: number;
209	}
210	
211	/** Every policy-wide modifier, as a rule that either applies to a policy or
212	 *  does not. Applicable rules stack. */
213	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
214	  {
215	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
216	    percent: -LOYALTY_DISCOUNT_PERCENT,
217	  },
218	  {
219	    appliesTo: () => true,
220	    percent: FIRST_INSURANCE_SURCHARGE_PERCENT,
221	  },
222	  {
223	    appliesTo: ({ precedingContracts }) => precedingContracts > 0,
224	    percent: -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
225	  },
226	];
227	
228	/** Policy-wide modifiers apply to the policy base premium — the sum of every
229	 *  item's base premium — not to any single item. */
230	const policyModifierAmount = (
231	  basePremium: number,
232	  context: PolicyContext,
233	): number =>
234	  sum(
235	    POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).map(
236	      (rule) => percentOf(basePremium, rule.percent),
237	    ),
238	  );
239	
240	const quote = (items: Item[], context: PolicyContext): QuoteResult => {
241	  const basePremium = policyBasePremium(items);
242	  // Every modifier is an amount added to the base premium, not a factor
243	  // compounded onto a running total: item-scoped modifiers take a percentage
244	  // of their own item's base premium, policy-wide ones take a percentage of
245	  // the policy base premium.
246	  const modifierAmounts = [
247	    ...items.map(itemModifierAmount),
248	    policyModifierAmount(basePremium, context),
249	  ];
250	  // The processing fee is added last, after all percentage modifiers.
251	  const premium = basePremium + sum(modifierAmounts) + PROCESSING_FEE;
252	  return { premium: roundPremium(premium) };
253	};
254	
255	/** The cap on everything a policy will ever pay out: twice the sum of the
256	 *  insured items' values. Premium modifiers do not raise it. */
257	const policyCap = (items: Item[]): number =>
258	  CAP_MULTIPLE * sum(items.map((item) => insuranceValueOfType(item.type)));
259	
260	/** What one damage entry reimburses before the deductible: the full damage,
261	 *  unless a special clause reduces it. */
262	const reimbursableAmount = (damage: Damage, insuredItem: Item): number =>
263	  (insuredItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
264	    ? percentOf(damage.amount, HALF_REIMBURSEMENT_PERCENT)
265	    : damage.amount;
266	
267	/** The insured item a damage entry refers to. A damage entry names only a
268	 *  type, while the clauses governing its reimbursement depend on the item.
269	 *  The cast is the one place this lookup is assumed to succeed: a damage
270	 *  entry for an item outside the policy is an error case that is not yet
271	 *  implemented, and this is where it will be handled. */
272	const insuredItemFor = (damage: Damage, policy: Policy): Item =>
273	  policy.items.find((item) => item.type === damage.itemType) as Item;
274	
275	/** What one damage entry pays out: the reimbursable amount, less the
276	 *  deductible that is charged once per damaged item. */
277	const damagePayout = (damage: Damage, policy: Policy): number =>
278	  reimbursableAmount(damage, insuredItemFor(damage, policy)) -
279	  DEDUCTIBLE_PER_DAMAGED_ITEM;
280	
281	/** The state that results from recording one policy against a step index,
282	 *  replacing any policy already recorded there. */
283	const withPolicy = (
284	  state: ScenarioState,
285	  stepIndex: number,
286	  policy: Policy,
287	): ScenarioState => ({
288	  ...state,
289	  policiesByStep: { ...state.policiesByStep, [stepIndex]: policy },
290	});
291	
292	/** Writes a policy, and records it so later claim steps can be paid against
293	 *  it. Each quote written also becomes a preceding contract for the next. */
294	const runQuote = (
295	  step: QuoteStep,
296	  stepIndex: number,
297	  state: ScenarioState,
298	): StepOutcome => ({
299	  result: quote(step.items, state),
300	  state: withPolicy(
301	    { ...state, precedingContracts: state.precedingContracts + 1 },
302	    stepIndex,
303	    { remainingCap: policyCap(step.items), items: step.items },
304	  ),
305	});
306	
307	/** Pays a claim against the policy an earlier quote step wrote, drawing the
308	 *  payout down from that policy's remaining cap. */
309	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
310	  const policy = state.policiesByStep[step.policy];
311	  const desiredPayout = sum(
312	    step.incident.damages.map((damage) => damagePayout(damage, policy)),
313	  );
314	  // A policy never pays out more than the cap it has left.
315	  const payout = Math.min(desiredPayout, policy.remainingCap);
316	  const remainingCap = policy.remainingCap - payout;
317	  return {
318	    result: { payout, remainingCap },
319	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
320	  };
321	};
322	
323	const runStep = (
324	  step: Step,
325	  stepIndex: number,
326	  state: ScenarioState,
327	): StepOutcome =>
328	  step.op === "quote"
329	    ? runQuote(step, stepIndex, state)
330	    : runClaim(step, state);
331	
332	export const runScenario = (scenario: Scenario): ScenarioResult => {
333	  const { results } = scenario.steps.reduce(
334	    ({ results, state }, step, stepIndex) => {
335	      const outcome = runStep(step, stepIndex, state);
336	      return { results: [...results, outcome.result], state: outcome.state };
337	    },
338	    { results: [] as StepResult[], state: initialState(scenario.customer) },
339	  );
340	  return { results };
341	};
